declare(strict_types=1);
date_default_timezone_set('America/New_York');

$files = [
    'mrl_wp_images.html' => [
        'b64' => '',
        'sha256' => 'e53f8759136929ba7b39fb5d3e1a234d55f6313a139a9a6790c5deb82e8e1db0'
    ],
    'mrl_wp_images_data.php' => [
        'b64' => '',
        'sha256' => '6d18ba22f87c2792470d70e337358ec40d36d58556533a6d6f75ff6bfa9e595e'
    ]
];

$report = [];
$ok = true;
$backupStamp = date('Ymd_His');

foreach ($files as $name => $spec) {
    $target = __DIR__ . DIRECTORY_SEPARATOR . $name;
    $data = base64_decode((string)$spec['b64'], true);

    if ($data === false) {
        $report[] = "ERROR: Could not decode $name";
        $ok = false;
        continue;
    }

    if (hash('sha256', $data) !== (string)$spec['sha256']) {
        $report[] = "ERROR: Embedded checksum failed for $name";
        $ok = false;
        continue;
    }

    if (is_file($target)) {
        $backup = $target . '.bak_' . $backupStamp;
        if (!copy($target, $backup)) {
            $report[] = "ERROR: Could not back up $name";
            $ok = false;
            continue;
        }
        $report[] = "Backup created: " . basename($backup);
    }

    $tmp = $target . '.tmp_' . bin2hex(random_bytes(4));

    if (file_put_contents($tmp, $data) === false) {
        $report[] = "ERROR: Could not write temporary file for $name";
        $ok = false;
        continue;
    }

    if (hash_file('sha256', $tmp) !== (string)$spec['sha256']) {
        @unlink($tmp);
        $report[] = "ERROR: Temporary checksum failed for $name";
        $ok = false;
        continue;
    }

    if (!@rename($tmp, $target)) {
        @unlink($tmp);
        $report[] = "ERROR: Could not install $name";
        $ok = false;
        continue;
    }

    $report[] = "Installed: $name";
}
